# SPDX-License-Identifier: MIT
# Decoders for a logic analyser's samples: 16-bit port values taken at a fixed rate, one pin a bit.
# Plain Python: the same on a board, in the simulator or on a PC.


def bit(samples, index, number):
    return (samples[index] >> number) & 1


def edges(samples, number, first=0, last=None):
    # Indices where the pin changes, between first and last.
    last = len(samples) if last is None else last
    mask = 1 << number
    found = []
    level = samples[first] & mask
    for i in range(first + 1, last):
        if (samples[i] & mask) != level:
            found.append(i)
            level = samples[i] & mask
    return found


def uart(samples, number, rate, baud):
    # 8N1, least significant bit first: [(index of the start bit, byte)]. A start without its stop
    # bit is a false start (the capture began inside a character): try again a sample later.
    per_bit = rate / baud
    mask = 1 << number
    found = []
    i = 1
    while i < len(samples):
        if not samples[i] & mask and samples[i - 1] & mask:
            stop = int(i + per_bit * 9.5)
            if stop >= len(samples):
                break
            if samples[stop] & mask:
                value = 0
                for k in range(8):
                    if samples[int(i + per_bit * (1.5 + k))] & mask:
                        value |= 1 << k
                found.append((i, value))
                i = stop
                continue
        i += 1
    return found


def spi(samples, clock, data, idle_low=True, bits=8):
    # Mode 0 (or 2 with idle_low False): data sampled on the clock's leading edge, most significant
    # bit first: [(index of the byte's first edge, byte)].
    mask = 1 << clock
    leading = []
    for i in range(1, len(samples)):
        now, before = samples[i] & mask, samples[i - 1] & mask
        if now != before and (bool(now) == idle_low):
            leading.append(i)
    found = []
    for start in range(0, len(leading) - bits + 1, bits):
        value = 0
        for i in leading[start : start + bits]:
            value = value << 1 | bit(samples, i, data)
        found.append((leading[start], value))
    return found


def pwm(samples, number, rate):
    # (frequency, share of the time high), from the rising edges; None without two of them.
    rising = [i for i in edges(samples, number) if bit(samples, i, number)]
    if len(rising) < 2:
        return None
    period = (rising[-1] - rising[0]) / (len(rising) - 1)
    high = sum(bit(samples, i, number) for i in range(rising[0], rising[-1]))
    return rate / period, high / (rising[-1] - rising[0])

# SPDX-License-Identifier: MIT
# The logic analyser's hardware: the Cortex-M4 samples GPIO port E (16 pins) at a fixed rate
# (mpy_m4.logic_capture), while the board's own buses send something to watch: UART7, SPI4 (both
# started by the capture, so their first bit is caught) or the PWM. Port E carries D0, D1 (UART7),
# D6 (PWM), D10 (chip select, a Linux GPIO line) and D11 to D13 (SPI4). In the Copper and Code Studio
# simulator the same signals are made up.

import array

try:
    import machine
    import mpy_m4

    HARDWARE = hasattr(mpy_m4, "logic_capture") and mpy_m4.available()
except ImportError:
    HARDWARE = False

# Rows on the screen: name, pin, bit of port E.
CHANNELS = [
    ("D1 TX", "PE8", 8),
    ("D6 PWM", "PE9", 9),
    ("D13 SCK", "PE12", 12),
    ("D11 MOSI", "PE14", 14),
    ("D12 MISO", "PE13", 13),
    ("D10 CS", "PE11", 11),
]
UART_BAUD = 115200
UART_TEXT = b"Hello, M4!"
SPI_BAUD = 250000
SPI_BYTES = b"\xa5\x3c\x0f"
PWM_HZ = 10000

# signal -> samples, rate
PLANS = {
    "UART": (2000, 1000000),
    "SPI": (1000, 2000000),
    "PWM": (2000, 1000000),
    "Nothing": (2000, 1000000),
}


class Board:
    def __init__(self):
        self._pwm = None
        self._cs = None

    def _quiet(self):
        if self._pwm is not None:
            self._pwm.deinit()
            self._pwm = None

    def capture(self, signal):
        count, rate = PLANS[signal]
        self._quiet()
        if signal == "UART":
            machine.UART(7, UART_BAUD)
            samples, rate, late = mpy_m4.logic_capture(count, rate, uart=UART_TEXT)
        elif signal == "SPI":
            machine.SPI(4, baudrate=SPI_BAUD, _miso_pull=1)
            if self._cs is None:
                self._cs = machine.Pin("PE11", machine.Pin.OUT, value=1)
            self._cs(0)  # chip select by Linux, around the transfer the M4 makes
            try:
                samples, rate, late = mpy_m4.logic_capture(count, rate, spi=SPI_BYTES)
            finally:
                self._cs(1)
        else:
            if signal == "PWM":
                self._pwm = machine.PWM("D6", freq=PWM_HZ, duty_u16=19661)  # 30%
            samples, rate, late = mpy_m4.logic_capture(count, rate)
        return samples, rate, late


def _uart_frames(text, baud, rate, start):
    # (index, level) changes of an 8N1 line sending text from sample start.
    per_bit = rate / baud
    changes = []
    t = start
    for value in text:
        levels = [0] + [(value >> k) & 1 for k in range(8)] + [1]
        for level in levels:
            changes.append((int(t), level))
            t += per_bit
    return changes


class Simulated:
    def capture(self, signal):
        count, rate = PLANS[signal]
        idle = (1 << 8) | (1 << 13) | (1 << 11)  # TX idle high, MISO pulled up, CS high
        samples = array.array("H", [idle] * count)
        lead = count // 20
        if signal == "UART":
            level = 1
            changes = _uart_frames(UART_TEXT, UART_BAUD, rate, lead)
            index = 0
            for i in range(count):
                while index < len(changes) and changes[index][0] <= i:
                    level = changes[index][1]
                    index += 1
                samples[i] = (samples[i] & ~(1 << 8)) | (level << 8)
        elif signal == "SPI":
            half = rate // SPI_BAUD // 2
            for i in range(lead - 10, count):
                samples[i] &= ~(1 << 11)  # CS low
            t = lead
            for value in SPI_BYTES:
                for k in range(7, -1, -1):
                    for j in range(2 * half):
                        if t + j < count:
                            sck = 1 if j >= half else 0
                            mosi = (value >> k) & 1
                            samples[t + j] = (samples[t + j] & ~((1 << 12) | (1 << 14))) | (sck << 12) | (mosi << 14)
                    t += 2 * half
        elif signal == "PWM":
            period = rate // PWM_HZ
            for i in range(count):
                if i % period < period * 3 // 10:
                    samples[i] |= 1 << 9
        return samples, float(rate), 0


hardware = Board() if HARDWARE else Simulated()
